-- 샘플 상담사(test@nhfire.co.kr)용 더미 상담 10건
-- 1) Authentication → Users → Add user 로 위 이메일 계정을 먼저 만든 뒤
-- 2) 이 파일 전체를 SQL Editor에 붙여넣고 Run 하세요. 여러 번 실행해도 같은 10건으로 덮어써요.

update public.profiles set name = '샘플 상담사', branch = '시연용', role = 'counselor', active = true
where id = (select id from auth.users where email = 'test@nhfire.co.kr');

insert into public.consults (id, counselor_id, consulted_at, data)
select v.id, u.id, v.at::timestamptz,
  -- 단계 이력의 작성자를 샘플 상담사로 채움
  jsonb_set(v.data::jsonb, '{enrollments}', coalesce((select jsonb_agg(jsonb_set(e, '{history}', (select jsonb_agg(h || jsonb_build_object('by', u.id)) from jsonb_array_elements(e->'history') h))) from jsonb_array_elements(v.data::jsonb->'enrollments') e), '[]'::jsonb))
from auth.users u, (values
